static inline const lv_image_dsc_t* uiIcon_idle_logo_192() {
    static lv_image_dsc_t d{};
    static bool ok = false;
    if (!ok) {
        d.header.magic = LV_IMAGE_HEADER_MAGIC;
        d.header.cf = LV_COLOR_FORMAT_RGB565A8;
        d.header.w = 192; d.header.h = 192; d.header.stride = 384;
        d.data_size = sizeof(ui_idle_logo_192_map);
        d.data = ui_idle_logo_192_map;
        ok = true;
    }
    return &d;
}

static lv_obj_t *g_uiIdleOverlay = nullptr;

static inline bool uiIdleIsOpen() {
    return g_uiIdleOverlay != nullptr;
}

static inline void uiIdleClose() {
    if (g_uiIdleOverlay) {
        lv_obj_delete(g_uiIdleOverlay);
        g_uiIdleOverlay = nullptr;
    }
}

static inline void uiIdleOpen() {
    if (g_uiIdleOverlay) return;
    lv_obj_t *bg = lv_obj_create(lv_layer_top());
    lv_obj_remove_style_all(bg);
    lv_obj_set_size(bg, UI_SCR_W, UI_SCR_H);
    lv_obj_set_pos(bg, 0, 0);
    lv_obj_set_style_bg_color(bg, lv_color_hex(UI_HEX_BG), LV_PART_MAIN);
    lv_obj_set_style_bg_opa(bg, LV_OPA_COVER, LV_PART_MAIN);
    lv_obj_add_flag(bg, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(bg, LV_OBJ_FLAG_SCROLLABLE);

    // Logo + email line: one centered flex column, equal distance to the top and bottom edges
    lv_obj_t *col = lv_obj_create(bg);
    lv_obj_remove_style_all(col);
    lv_obj_remove_flag(col, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(col, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_size(col, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(col, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(col, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_row(col, 4, LV_PART_MAIN);   // the logo has a ~4 px transparent margin at the bottom, so the visible gap to the email is ~8 px

    lv_obj_t *img = lv_image_create(col);
    lv_image_set_src(img, uiIcon_idle_logo_192());
    lv_obj_set_style_image_recolor_opa(img, LV_OPA_TRANSP, LV_PART_MAIN);
    lv_obj_remove_flag(img, LV_OBJ_FLAG_CLICKABLE);

    // Orange "Email:" + cream address: two labels in one flex row (LVGL 9.2 has no label recolor)
    lv_obj_t *mailRow = lv_obj_create(col);
    lv_obj_remove_style_all(mailRow);
    lv_obj_remove_flag(mailRow, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(mailRow, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_size(mailRow, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(mailRow, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(mailRow, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(mailRow, 4, LV_PART_MAIN);

    lv_obj_t *mailTag = lv_label_create(mailRow);
    lv_label_set_text(mailTag, "Email:");
    lv_obj_set_style_text_font(mailTag, UI_FONT_T5, LV_PART_MAIN);
    lv_obj_set_style_text_color(mailTag, lv_color_hex(UI_HEX_ORANGE), LV_PART_MAIN);

    lv_obj_t *mailAddr = lv_label_create(mailRow);
    lv_label_set_text(mailAddr, ABOUT_EMAIL);   // address from RoasterSetting.h
    lv_obj_set_style_text_font(mailAddr, UI_FONT_T5, LV_PART_MAIN);
    lv_obj_set_style_text_color(mailAddr, lv_color_hex(UI_HEX_TEXT), LV_PART_MAIN);

    lv_obj_center(col);

    g_uiIdleOverlay = bg;
}
